// Find the newest entry in this batch and update the connection's timestamp
// so that the next poll only fetches entries newer than this one
const entries = msg.payload;

if (entries.length > 0) {
    const newestEntry = entries.reduce((a, b) =>
        a.timeCreated > b.timeCreated ? a : b
    );

    const connectionId = newestEntry.connection_id
        || (msg.connection && msg.connection.id);
    const sourceSystem = newestEntry.client;

    if (connectionId && sourceSystem) {
        const data = global.get("parat_bridge");
        const connection = data.connections.find(c => c.id === connectionId);

        if (connection) {
            connection.timestamps["last_" + sourceSystem] = newestEntry.timeCreated;
            global.set("parat_bridge", data);
        }
    }
}

return msg;
